var ui=Bulldozer.UI.QuarryGameUI.Instance;var e=ui.equipment;ui.player.autoMine=false;ui.Refresh();System.GC.Collect();long before=UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong();var sw=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<500;i++)ui.Refresh();sw.Stop();System.IO.File.WriteAllText("Maintenance/Mobile/ui-refresh-after.txt","Closed UI Refresh 500 calls: Mono used delta="+(UnityEngine.Profiling.Profiler.GetMonoUsedSizeLong()-before)+" bytes, elapsed="+sw.Elapsed.TotalMilliseconds+"ms (Editor microbenchmark)");
var original=e.Snapshot;var report=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,msg)=>report.Add((ok?"PASS ":"FAIL ")+msg);ui.Open("inventory");var s=e.Snapshot;s.items=new[]{0,0,6};s.backpackItems=System.Array.Empty<int>();s.barrowItems=new[]{1,7};s.refineryInput=new[]{2,2};s.refineryOutput=new[]{8};s.loadingQueue=new[]{9,9};s.truckItems=new[]{10};check(e.Commit(s),"Valid inventory fixture accepted");
ui.SelectStorage(0);check(ui.inventoryCounts[0].text=="2 RAW   /   1 REFINED","Carrying tab retains exact raw/refined counts");ui.SelectStorage(1);check(ui.inventoryCounts[1].text=="1 RAW   /   1 REFINED","Parked tab combines stored items correctly");ui.SelectStorage(2);check(ui.inventoryCounts[2].text=="2 RAW   /   1 REFINED","Refinery tab counts both input/output without concatenating arrays");ui.SelectStorage(3);check(ui.inventoryCounts[3].text=="0 RAW   /   2 REFINED"&&ui.inventoryCounts[4].text=="0 RAW   /   1 REFINED","Loading tab includes queued and on-truck items");
ui.Open("upgrades");check(ui.upgradeValues[0].text.StartsWith("POWER")&&ui.upgradePrices[0].text.Contains(e.DamageCost.ToString()),"Upgrade cards populate on opening");ui.Open("settings");check(!string.IsNullOrEmpty(ui.performanceLabel.text),"Settings labels populate on opening");e.Commit(original);ui.Refresh();check(ui.cash.text=="$"+original.coins,"Cash updates independently of panel visibility");ui.Close();System.IO.File.WriteAllLines("Maintenance/Mobile/ui-regression.txt",report);return string.Join("\n",report);

